    for r in range(h):
        for c in (0,w-1):
            if grid[r][c]!=bg: rails.append(('h',r,c,grid[r][c]))
    for r in range(h):
        for c in range(w):
            color=grid[r][c]
            if color==bg: continue
            # Ignore all cells belonging to border rails.
            if r in (0,h-1) or c in (0,w-1): continue
            options=[]
            for axis,a,b,railcolor in rails:
                if railcolor==color: continue
                if axis=='v' and a==c: options.append((abs(b-r),axis,b))
                if axis=='h' and a==r: options.append((abs(b-c),axis,b))
            if not options: continue
            _,axis,target=min(options)
            out[r][c]=4
            if axis=='v':
                step=1 if target>r else -1
                y=r+step
                while y!=target:
                    if grid[y][c]==bg: out[y][c]=color
                    y+=step
            else:
                step=1 if target>c else -1
                x=c+step
                while x!=target:
                    if grid[r][x]==bg: out[r][x]=color
                    x+=step
